import { useEffect, useState, type RefObject } from 'react';

type UseIntersectionVisibleOptions = {
  rootMargin?: string;
  threshold?: number;
};

/**
 * Returns true once the target element intersects the viewport (or root).
 * Useful for deferring expensive API calls until a panel is near-visible.
 */
export function useIntersectionVisible(
  targetRef: RefObject<Element | null>,
  options: UseIntersectionVisibleOptions = {}
): boolean {
  const { rootMargin = '200px', threshold = 0 } = options;
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const node = targetRef.current;
    if (!node || visible) {
      return undefined;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setVisible(true);
        }
      },
      { rootMargin, threshold }
    );

    observer.observe(node);
    return () => observer.disconnect();
  }, [targetRef, rootMargin, threshold, visible]);

  return visible;
}
