import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Checkbox,
  CircularProgress,
  FormControl,
  FormControlLabel,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { reportingTabHref } from '../../constants/reportingTabs';
import ApiService from '../../services/api';
import {
  complianceWorkflowStatusLabel,
  INDIA_COMPLIANCE_GROUPS,
  INDIA_COMPLIANCE_SECTIONS,
  unwrapComplianceHubPayload,
} from '../../constants/complianceHub';
import { useUrlSectionParam } from '../../hooks/useUrlSectionParam';
import { useOrchestrationEvents } from '../../hooks/useOrchestrationEvents';
import ComplianceTrackShell from './ComplianceTrackShell';
import SupplierPrimaryDataPanel from './SupplierPrimaryDataPanel';
import CarbonPassportPanel from './CarbonPassportPanel';
import PatAbatementCurvePanel from './PatAbatementCurvePanel';
import ComplianceJsonPanel from './ComplianceJsonPanel';
import ComplianceReadinessGrid from './ComplianceReadinessGrid';
import ComplianceReadinessGapPanel, { type ModuleGapBundle } from './ComplianceReadinessGapPanel';
import { type PrioritizedReadinessAction } from './ComplianceReadinessActionQueue';
import MsmeReadinessChecklist from './MsmeReadinessChecklist';
import { INDIA_READINESS_MODULE_KEYS } from '../../constants/readinessModuleKeys';
import QuantificationMethodBanner from '../shared/QuantificationMethodBanner';
import IsoGapClosurePanel from './IsoGapClosurePanel';
import AssuranceClauseWorkflowPanel, {
  type AssuranceClauseWorkflowBundle,
} from './AssuranceClauseWorkflowPanel';
import RecalculationPolicyPanel from './RecalculationPolicyPanel';
import GhgInventoryHistoryPanel from './GhgInventoryHistoryPanel';
import GpsGeotaggedCapture from './GpsGeotaggedCapture';
import OrchestrationRunPanel, { type OrchestrationRunSummary, stagesFromRun } from './OrchestrationRunPanel';
import { MODULE_CHECK_LABELS } from '../../constants/orchestrationUxLabels';
import useReadinessLocale from '../../hooks/useReadinessLocale';
import ApplicationWarningResolver from '../shared/ApplicationWarningResolver';
import { resolveTrackItemLabel } from '../../constants/complianceTrackLocale';
import { type IcmIntegrationConfig } from '../icm/IndianCarbonMarketPanel';

const SECTION_IDS = INDIA_COMPLIANCE_SECTIONS.map((s) => s.id);

type IndiaComplianceTrackProps = {
  variant?: 'msme' | 'enterprise';
};

const IndiaComplianceTrack: React.FC<IndiaComplianceTrackProps> = ({ variant = 'msme' }) => {
  const isEnterprise = variant === 'enterprise';
  useOrchestrationEvents(true);
  const { strings, locale } = useReadinessLocale();
  const [section, setSection] = useUrlSectionParam('overview', SECTION_IDS);
  const [period, setPeriod] = useState('annual');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [track, setTrack] = useState<Record<string, unknown> | null>(null);
  const [sbtiForm, setSbtiForm] = useState<Record<string, unknown>>({});
  const [saving, setSaving] = useState(false);
  const [newPlan, setNewPlan] = useState({
    title: '',
    scope: 'organization',
    targetReductionPercent: 10,
    dueDate: '',
  });
  const [zedForm, setZedForm] = useState<Record<string, unknown>>({});
  const [brsrFilingForm, setBrsrFilingForm] = useState<Record<string, unknown>>({});
  const [isoOrchestrating, setIsoOrchestrating] = useState(false);
  const [brsrOrchestrating, setBrsrOrchestrating] = useState(false);
  const [orchestrationFeedback, setOrchestrationFeedback] = useState<string | null>(null);
  const [lastIsoRun, setLastIsoRun] = useState<OrchestrationRunSummary | null>(null);
  const [lastBrsrRun, setLastBrsrRun] = useState<OrchestrationRunSummary | null>(null);
  const [isoStages, setIsoStages] = useState<Array<{ stage: string; status: string; durationMs?: number | null }>>([]);
  const [brsrStages, setBrsrStages] = useState<Array<{ stage: string; status: string; durationMs?: number | null }>>([]);

  const runIsoAssuranceOrchestration = async () => {
    setIsoOrchestrating(true);
    setOrchestrationFeedback(null);
    try {
      const res = await ApiService.orchestrateIsoAssurance({ period });
      const data = (res as { data?: Record<string, unknown> })?.data;
      setIsoStages((data?.stages as typeof isoStages) || []);
      setLastIsoRun((data?.orchestrationRun as OrchestrationRunSummary) || {
        orchestratorType: 'iso_assurance',
        scoreAfter: data?.overallReadinessScore as number,
        message: data?.message as string,
        lastRunAt: new Date().toISOString(),
        success: data?.success !== false
      });
      setOrchestrationFeedback(String(data?.message || strings.isoAssuranceComplete));
      await load();
    } catch (e) {
      setOrchestrationFeedback(e instanceof Error ? e.message : strings.isoAssuranceFailed);
    } finally {
      setIsoOrchestrating(false);
    }
  };

  const runBrsrDisclosureOrchestration = async () => {
    setBrsrOrchestrating(true);
    setOrchestrationFeedback(null);
    try {
      const res = await ApiService.orchestrateBrsrDisclosure({ period });
      const data = (res as { data?: Record<string, unknown> })?.data;
      setBrsrStages((data?.stages as typeof brsrStages) || []);
      setLastBrsrRun((data?.orchestrationRun as OrchestrationRunSummary) || {
        orchestratorType: 'brsr_disclosure',
        scoreAfter: data?.overallReadinessScore as number,
        message: data?.message as string,
        lastRunAt: new Date().toISOString(),
        success: data?.success !== false
      });
      setOrchestrationFeedback(String(data?.message || strings.brsrDisclosureComplete));
      await load();
    } catch (e) {
      setOrchestrationFeedback(e instanceof Error ? e.message : strings.brsrDisclosureFailed);
    } finally {
      setBrsrOrchestrating(false);
    }
  };

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getComplianceIndiaTrack({ period });
      const data = unwrapComplianceHubPayload<Record<string, unknown>>(res);
      setTrack(data);
      const sbti = (data?.modules as Record<string, unknown>)?.sbtiTargets;
      if (sbti && typeof sbti === 'object') {
        setSbtiForm(sbti as Record<string, unknown>);
      }
      const zedProfile = (data?.modules as Record<string, unknown>)?.zedCertificationProfile;
      if (zedProfile && typeof zedProfile === 'object') {
        setZedForm(zedProfile as Record<string, unknown>);
      }
      const brsrFiling = (data?.modules as Record<string, unknown>)?.brsrFilingProfile;
      if (brsrFiling && typeof brsrFiling === 'object') {
        setBrsrFilingForm(brsrFiling as Record<string, unknown>);
      }
      const agentOrch = (data?.agentOrchestration || {}) as {
        lastRuns?: Record<string, OrchestrationRunSummary>;
      };
      const lastRuns = agentOrch.lastRuns || {};
      if (lastRuns.iso_assurance) {
        setLastIsoRun(lastRuns.iso_assurance);
        setIsoStages(stagesFromRun(lastRuns.iso_assurance));
      }
      if (lastRuns.brsr_disclosure) {
        setLastBrsrRun(lastRuns.brsr_disclosure);
        setBrsrStages(stagesFromRun(lastRuns.brsr_disclosure));
      }
    } catch (e) {
      setTrack(null);
      setError(e instanceof Error ? e.message : 'Failed to load India compliance track');
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => {
    load();
  }, [load]);

  const modules = (track?.modules || {}) as Record<string, unknown>;
  const readiness = (track?.readiness || {}) as Record<string, string>;
  const moduleScores = (track?.moduleScores || {}) as Record<string, number | null>;
  const thresholds = (track?.thresholds || {}) as Record<string, number>;
  const indiaOverall = track?.indiaOverallReadinessScore as number | null | undefined;
  const moduleGapDetails = (track?.moduleGapDetails || {}) as Record<string, ModuleGapBundle>;
  const prioritizedActions = (track?.prioritizedActions || []) as PrioritizedReadinessAction[];
  const assuranceClauseWorkflows = track?.assuranceClauseWorkflows as AssuranceClauseWorkflowBundle | undefined;
  const dataQualityAdvisory = track?.dataQualityAdvisory as {
    spendProxySharePct?: number;
    accuracyLevel?: string;
    recommendations?: Array<{ title?: string; action?: string }>;
  } | undefined;

  const saveSbti = async () => {
    setSaving(true);
    try {
      await ApiService.updateComplianceSbtiTargets(sbtiForm);
      await load();
    } finally {
      setSaving(false);
    }
  };

  const toggleAssuranceCheckpoint = async (checkpoints: { id: string; label: string; completed: boolean }[]) => {
    await ApiService.updateComplianceAssurance({ checkpoints });
    await load();
  };

  const saveZedProfile = async (patch: Record<string, unknown>) => {
    setSaving(true);
    try {
      await ApiService.updateComplianceZedCertification({ ...zedForm, ...patch });
      await load();
    } finally {
      setSaving(false);
    }
  };

  const saveBrsrFilingProfile = async () => {
    setSaving(true);
    try {
      await ApiService.updateComplianceBrsrFilingProfile(brsrFilingForm);
      await load();
    } finally {
      setSaving(false);
    }
  };

  const addActionPlan = async () => {
    if (!newPlan.title.trim()) return;
    setSaving(true);
    try {
      await ApiService.createComplianceActionPlan(newPlan);
      setNewPlan({ title: '', scope: 'organization', targetReductionPercent: 10, dueDate: '' });
      await load();
    } finally {
      setSaving(false);
    }
  };

  const renderSection = () => {
    if (loading && !track) {
      return (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
          <CircularProgress />
        </Box>
      );
    }

    if (!track) {
      return null;
    }

    switch (section) {
      case 'overview':
        return (
          <>
            {indiaOverall != null ? (
              <Alert severity="info" sx={{ mb: 2 }}>
                India market reporting readiness: <strong>{Math.round(indiaOverall)}%</strong>
              </Alert>
            ) : null}
            <Alert severity="info" sx={{ mb: 2 }} action={(
              <Button component={RouterLink} to="/compliance" variant="contained" size="small">
                Check readiness
              </Button>
            )}>
              <Typography variant="body2">
                {strings.indiaHubHandoff}
              </Typography>
            </Alert>
            <ComplianceReadinessGrid
              locale={locale}
              items={[
                { key: 'brsr', label: resolveTrackItemLabel('brsr', locale, 'BRSR Core'), status: readiness.brsrCore, score: moduleScores.brsrCore, threshold: thresholds.brsrDisclosurePrep },
                { key: 'iso', label: resolveTrackItemLabel('iso', locale, 'ISO assurance'), status: readiness.isoAssurance, score: moduleScores.isoAssurance, threshold: thresholds.isoAssurancePrep },
                { key: 'pat', label: resolveTrackItemLabel('patIntensity', locale, 'PAT intensity'), status: readiness.patIntensity, score: moduleScores.patIntensity, threshold: thresholds.patReadiness },
                { key: 'zed', label: resolveTrackItemLabel('zedCertification', locale, 'ZED certification'), status: readiness.zedCertification, score: moduleScores.zedCertification },
                { key: 'sbti', label: resolveTrackItemLabel('sbti', locale, 'SBTi'), status: readiness.sbti, score: moduleScores.sbti, threshold: thresholds.sbtiReadiness },
                { key: 'sync', label: resolveTrackItemLabel('sync', locale, 'Data sync'), status: readiness.accountingSync, score: moduleScores.accountingSync },
                { key: 'tier1', label: resolveTrackItemLabel('tier1', locale, 'Tier 1 data'), status: readiness.tier1DataQuality, score: moduleScores.tier1DataQuality },
              ]}
            />
            <MsmeReadinessChecklist
              prioritizedActions={prioritizedActions}
              moduleGapDetails={moduleGapDetails}
              moduleKeys={[...INDIA_READINESS_MODULE_KEYS]}
              overallReadinessScore={indiaOverall}
              period={period}
              onRefresh={() => void load()}
              layout="embedded"
              showExpandedDetails
            />
          </>
        );
      case 'brsr-core': {
        const xbrlReadiness = (modules.brsrXbrlReadiness || {}) as {
          valid?: boolean;
          missingElements?: string[];
          listedEntity?: boolean;
          taxonomyVersion?: string;
        };
        return (
          <Stack spacing={2}>
            {orchestrationFeedback ? <Alert severity="info">{orchestrationFeedback}</Alert> : null}
            <OrchestrationRunPanel
              lastRun={lastBrsrRun}
              stages={brsrStages}
              title={MODULE_CHECK_LABELS.brsr.panelTitle}
              running={brsrOrchestrating}
              runningStageLabel={MODULE_CHECK_LABELS.brsr.running}
              showEmptyPrompt
            />
            <Typography variant="body2" color="text.secondary">
              {MODULE_CHECK_LABELS.brsr.subtitle}
            </Typography>
            <Stack direction="row" spacing={1} flexWrap="wrap">
              <Button
                variant="contained"
                disabled={brsrOrchestrating}
                onClick={() => void runBrsrDisclosureOrchestration()}
              >
                {brsrOrchestrating ? MODULE_CHECK_LABELS.brsr.running : MODULE_CHECK_LABELS.brsr.button}
              </Button>
              <Button component={RouterLink} to={reportingTabHref('brsr')} variant="outlined">
                Open BRSR report
              </Button>
            </Stack>
            <Alert severity={xbrlReadiness.valid ? 'success' : 'info'}>
              SEBI BRSR XBRL ({xbrlReadiness.taxonomyVersion || 'in-bsrs-2021-09-01'}):
              {xbrlReadiness.valid
                ? ' Ready for BSE/NSE utility validation.'
                : ` Missing: ${(xbrlReadiness.missingElements || []).join(', ') || 'review filing profile'}.`}
            </Alert>
            <Alert severity="info">{strings.brsrScopeNotice}</Alert>
            <ComplianceReadinessGapPanel
              moduleGapDetails={moduleGapDetails}
              moduleKeys={['brsrCore']}
              title="BRSR gaps to close"
              period={period}
              onResolved={() => void load()}
            />
            <AssuranceClauseWorkflowPanel
              bundle={assuranceClauseWorkflows}
              frameworkFilter="brsr"
              title="BRSR Principle 6 clause workflows"
            />
            <Card variant="outlined">
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Listed entity filing profile
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                  {isEnterprise
                    ? 'Listed enterprises: CIN and stock exchange sync from your enterprise profile. Add ISIN and scrip code here or under Enterprise profile.'
                    : 'Listed MSMEs: CIN and stock exchange sync from My Company → Listed company (BRSR/XBRL). You can also edit ISIN and scrip code here.'}
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12}>
                    <FormControlLabel
                      control={
                        <Checkbox
                          checked={Boolean(brsrFilingForm.isListedEntity)}
                          onChange={(e) =>
                            setBrsrFilingForm({ ...brsrFilingForm, isListedEntity: e.target.checked })
                          }
                        />
                      }
                      label="Listed on BSE/NSE (or other Indian stock exchange)"
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="CIN"
                      fullWidth
                      value={brsrFilingForm.cin || ''}
                      onChange={(e) => setBrsrFilingForm({ ...brsrFilingForm, cin: e.target.value })}
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="ISIN"
                      fullWidth
                      value={brsrFilingForm.isin || ''}
                      onChange={(e) => setBrsrFilingForm({ ...brsrFilingForm, isin: e.target.value })}
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="Stock exchange"
                      fullWidth
                      placeholder="e.g. BSE, NSE"
                      value={brsrFilingForm.stockExchange || ''}
                      onChange={(e) =>
                        setBrsrFilingForm({ ...brsrFilingForm, stockExchange: e.target.value })
                      }
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="Scrip code"
                      fullWidth
                      value={brsrFilingForm.scripCode || ''}
                      onChange={(e) =>
                        setBrsrFilingForm({ ...brsrFilingForm, scripCode: e.target.value })
                      }
                    />
                  </Grid>
                </Grid>
                <Stack direction="row" spacing={1} sx={{ mt: 2 }} flexWrap="wrap" useFlexGap>
                  <Button variant="contained" onClick={saveBrsrFilingProfile} disabled={saving}>
                    Save filing profile
                  </Button>
                  {!isEnterprise && (
                    <Button component={RouterLink} to="/msme-profile" variant="outlined">
                      Edit listed company in My Company
                    </Button>
                  )}
                  <Button
                    component={RouterLink}
                    to={reportingTabHref('brsr')}
                    variant="outlined"
                  >
                    Download SEBI XBRL from BRSR report
                  </Button>
                </Stack>
              </CardContent>
            </Card>
            <ComplianceJsonPanel
              title="BRSR Core supplier pack (JSON)"
              data={modules.brsrCoreSupplierPack}
              filename="brsr-core-supplier-pack.json"
            />
          </Stack>
        );
      }
      case 'iso-assurance': {
        const assurance = modules.iso14064Assurance as Record<string, unknown>;
        const checkpoints = (assurance?.checkpoints || []) as {
          id: string;
          label: string;
          completed: boolean;
        }[];
        return (
          <Stack spacing={2}>
            {orchestrationFeedback ? <Alert severity="info">{orchestrationFeedback}</Alert> : null}
            <OrchestrationRunPanel
              lastRun={lastIsoRun}
              stages={isoStages}
              title={MODULE_CHECK_LABELS.iso.panelTitle}
              running={isoOrchestrating}
              runningStageLabel={MODULE_CHECK_LABELS.iso.running}
              showEmptyPrompt
            />
            <GpsGeotaggedCapture
              workflow="iso_site_evidence"
              period={period}
              onComplete={() => void load()}
            />
            <Typography variant="body2" color="text.secondary">
              {MODULE_CHECK_LABELS.iso.subtitle}
            </Typography>
            <Stack direction="row" spacing={1} flexWrap="wrap">
              <Button
                variant="contained"
                disabled={isoOrchestrating}
                onClick={() => void runIsoAssuranceOrchestration()}
              >
                {isoOrchestrating ? MODULE_CHECK_LABELS.iso.running : MODULE_CHECK_LABELS.iso.button}
              </Button>
              <Button component={RouterLink} to={reportingTabHref('iso14064')} variant="outlined">
                Open ISO 14064 disclosure report
              </Button>
            </Stack>
            <Alert severity="info">
              Overall readiness score:{' '}
              <strong>{Number(assurance?.overallReadinessScore || 0)}%</strong>. Complete checkpoints
              before limited assurance.
            </Alert>
            {dataQualityAdvisory?.spendProxySharePct != null
              && dataQualityAdvisory.spendProxySharePct >= 40 ? (
                <Alert severity="warning">
                  {strings.spendProxyWarning}
                  {' '}
                  ({dataQualityAdvisory.spendProxySharePct}% spend-proxy transactions detected.)
                  <ApplicationWarningResolver
                    compact
                    warnings={[{
                      type: 'spend_proxy',
                      message: strings.spendProxyWarning,
                    }]}
                  />
                </Alert>
              ) : null}
            <ComplianceReadinessGapPanel
              moduleGapDetails={moduleGapDetails}
              moduleKeys={['isoAssurance', 'patIntensity']}
              title="ISO assurance gaps"
              period={period}
              onResolved={() => void load()}
            />
            <Card variant="outlined">
              <CardContent>
                {checkpoints.map((cp) => (
                  <FormControlLabel
                    key={cp.id}
                    control={
                      <Checkbox
                        checked={cp.completed}
                        onChange={(e) => {
                          const next = checkpoints.map((c) =>
                            c.id === cp.id ? { ...c, completed: e.target.checked } : c
                          );
                          toggleAssuranceCheckpoint(next);
                        }}
                      />
                    }
                    label={cp.label}
                  />
                ))}
              </CardContent>
            </Card>
            <RecalculationPolicyPanel />
            <GhgInventoryHistoryPanel />
            <AssuranceClauseWorkflowPanel
              bundle={assuranceClauseWorkflows}
              frameworkFilter="iso14064"
              title="ISO 14064 clause assurance workflows"
            />
            <IsoGapClosurePanel period={period} />
          </Stack>
        );
      }
      case 'pat-intensity': {
        const pat = modules.patEnergyIntensity as {
          energyEmissionsKgCo2e?: number;
          energySharePercent?: number;
          intensityPerCrInrTurnover?: number | null;
          readinessScore?: number;
          readinessFactors?: string[];
          patRelevanceNote?: string;
        };
        return (
          <Stack spacing={2}>
            <GpsGeotaggedCapture
              workflow="pat_facility_evidence"
              period={period}
              onComplete={() => void load()}
            />
          <Grid container spacing={2}>
            <Grid item xs={12} md={4}>
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="subtitle2" color="text.secondary">
                    Energy emissions
                  </Typography>
                  <Typography variant="h5">
                    {Number(pat?.energyEmissionsKgCo2e || 0).toLocaleString('en-IN')} kg
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} md={4}>
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="subtitle2" color="text.secondary">
                    Energy share of total
                  </Typography>
                  <Typography variant="h5">{Number(pat?.energySharePercent || 0)}%</Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} md={4}>
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="subtitle2" color="text.secondary">
                    Intensity / ₹ Cr turnover
                  </Typography>
                  <Typography variant="h5">
                    {pat?.intensityPerCrInrTurnover != null
                      ? Number(pat.intensityPerCrInrTurnover).toLocaleString('en-IN')
                      : '—'}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12}>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                PAT readiness score:{' '}
                <strong>{Number(pat?.readinessScore ?? 0)}%</strong>
                {pat?.readinessFactors?.length ? (
                  <> · factors: {pat.readinessFactors.join(', ')}</>
                ) : null}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {String(pat?.patRelevanceNote || '')}
              </Typography>
            </Grid>
          </Grid>
          <PatAbatementCurvePanel />
          </Stack>
        );
      }
      case 'sbti-plans':
        return (
          <Stack spacing={3}>
            <Card variant="outlined">
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  SBTi-style targets
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={6} md={3}>
                    <TextField
                      label="Base year"
                      type="number"
                      fullWidth
                      value={sbtiForm.baseYear ?? ''}
                      onChange={(e) =>
                        setSbtiForm({ ...sbtiForm, baseYear: Number(e.target.value) })
                      }
                    />
                  </Grid>
                  <Grid item xs={6} md={3}>
                    <TextField
                      label="Near-term target year"
                      type="number"
                      fullWidth
                      value={sbtiForm.nearTermTargetYear ?? ''}
                      onChange={(e) =>
                        setSbtiForm({ ...sbtiForm, nearTermTargetYear: Number(e.target.value) })
                      }
                    />
                  </Grid>
                  <Grid item xs={6} md={3}>
                    <TextField
                      label="Reduction %"
                      type="number"
                      fullWidth
                      value={sbtiForm.nearTermReductionPercent ?? ''}
                      onChange={(e) =>
                        setSbtiForm({
                          ...sbtiForm,
                          nearTermReductionPercent: Number(e.target.value),
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={6} md={3}>
                    <FormControl fullWidth>
                      <InputLabel>Status</InputLabel>
                      <Select
                        label="Status"
                        value={sbtiForm.status || 'not_started'}
                        onChange={(e) => setSbtiForm({ ...sbtiForm, status: e.target.value })}
                      >
                        <MenuItem value="not_started">Not started</MenuItem>
                        <MenuItem value="committed">Committed</MenuItem>
                        <MenuItem value="targets_set">Targets set</MenuItem>
                        <MenuItem value="submitted">Submitted to SBTi</MenuItem>
                        <MenuItem value="validated">Validated</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>
                </Grid>
                <Button sx={{ mt: 2 }} variant="contained" onClick={saveSbti} disabled={saving}>
                  Save targets
                </Button>
              </CardContent>
            </Card>
            <Card variant="outlined">
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Reduction action plans
                </Typography>
                <Grid container spacing={2} sx={{ mb: 2 }}>
                  <Grid item xs={12} md={5}>
                    <TextField
                      label="Plan title"
                      fullWidth
                      value={newPlan.title}
                      onChange={(e) => setNewPlan({ ...newPlan, title: e.target.value })}
                    />
                  </Grid>
                  <Grid item xs={6} md={3}>
                    <TextField
                      label="Target reduction %"
                      type="number"
                      fullWidth
                      value={newPlan.targetReductionPercent}
                      onChange={(e) =>
                        setNewPlan({
                          ...newPlan,
                          targetReductionPercent: Number(e.target.value),
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={6} md={4}>
                    <Button variant="contained" onClick={addActionPlan} disabled={saving}>
                      Add plan
                    </Button>
                  </Grid>
                </Grid>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Title</TableCell>
                      <TableCell>Scope</TableCell>
                      <TableCell>Reduction %</TableCell>
                      <TableCell>Status</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {((modules.actionPlans as Record<string, unknown>[]) || []).map((plan) => (
                      <TableRow key={String(plan._id)}>
                        <TableCell>{String(plan.title)}</TableCell>
                        <TableCell>{String(plan.scope)}</TableCell>
                        <TableCell>{Number(plan.targetReductionPercent || 0)}%</TableCell>
                        <TableCell>{complianceWorkflowStatusLabel(String(plan.status))}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
                <Button
                  component={RouterLink}
                  to="/emissions-reduction-targets"
                  sx={{ mt: 2 }}
                  size="small"
                >
                  Open emissions targets dashboard
                </Button>
              </CardContent>
            </Card>
          </Stack>
        );
      case 'zed-certification': {
        const zed = modules.zedCertification as Record<string, unknown>;
        const pillarScores = (zed?.pillarScores || []) as {
          id: string;
          label: string;
          readinessScore: number;
          gaps: number;
        }[];
        const subsidy = zed?.subsidyEstimate as Record<string, unknown>;
        const priorityActions = (zed?.priorityActions || []) as {
          priority: string;
          action: string;
          detail: string;
        }[];
        const eligibility = zed?.eligibility as Record<string, unknown>;
        return (
          <Stack spacing={2}>
            <Alert severity={eligibility?.eligible ? 'info' : 'warning'}>
              {eligibility?.eligible
                ? `ZED readiness score: ${Number(zed?.overallReadinessScore || 0)}%. Target level: ${String(zed?.targetLevel || 'bronze')}.`
                : 'Complete UDYAM registration and confirm manufacturing sector to qualify for MSME ZED certification.'}
            </Alert>
            <Grid container spacing={2}>
              {pillarScores.map((pillar) => (
                <Grid item xs={12} sm={6} md={3} key={pillar.id}>
                  <Card variant="outlined">
                    <CardContent>
                      <Typography variant="subtitle2" color="text.secondary">
                        {pillar.label}
                      </Typography>
                      <Typography variant="h5">{pillar.readinessScore}%</Typography>
                      <Typography variant="caption" color="text.secondary">
                        {pillar.gaps} open gaps
                      </Typography>
                    </CardContent>
                  </Card>
                </Grid>
              ))}
            </Grid>
            <Card variant="outlined">
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Certification journey
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={4}>
                    <FormControl fullWidth>
                      <InputLabel>Target level</InputLabel>
                      <Select
                        label="Target level"
                        value={zedForm.targetLevel || zed?.targetLevel || 'bronze'}
                        onChange={(e) => setZedForm({ ...zedForm, targetLevel: e.target.value })}
                      >
                        <MenuItem value="bronze">Bronze</MenuItem>
                        <MenuItem value="silver">Silver</MenuItem>
                        <MenuItem value="gold">Gold</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <FormControlLabel
                      control={
                        <Checkbox
                          checked={Boolean(zedForm.pledgeTaken ?? zed?.pledgeTaken)}
                          onChange={(e) =>
                            setZedForm({ ...zedForm, pledgeTaken: e.target.checked })
                          }
                        />
                      }
                      label="ZED pledge taken on zed.msme.gov.in"
                    />
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <FormControl fullWidth>
                      <InputLabel>Certified level</InputLabel>
                      <Select
                        label="Certified level"
                        value={zedForm.certifiedLevel || zed?.certifiedLevel || ''}
                        onChange={(e) =>
                          setZedForm({ ...zedForm, certifiedLevel: e.target.value || null })
                        }
                      >
                        <MenuItem value="">Not certified</MenuItem>
                        <MenuItem value="bronze">Bronze</MenuItem>
                        <MenuItem value="silver">Silver</MenuItem>
                        <MenuItem value="gold">Gold</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>
                </Grid>
                <Button
                  sx={{ mt: 2, mr: 1 }}
                  variant="contained"
                  onClick={() => saveZedProfile(zedForm)}
                  disabled={saving}
                >
                  Save ZED profile
                </Button>
                <Button
                  component="a"
                  href="https://zed.msme.gov.in/"
                  target="_blank"
                  rel="noopener noreferrer"
                  variant="outlined"
                >
                  Open official ZED portal
                </Button>
              </CardContent>
            </Card>
            {subsidy && (
              <Alert severity="success">
                Estimated net payable for {String(subsidy.targetLevel)}: ₹
                {Number(subsidy.estimatedNetPayableInr || 0).toLocaleString('en-IN')} (
                {Number((Number(subsidy.effectiveSubsidyRate || 0) * 100).toFixed(0))}% subsidy).
                {subsidy.note ? ` ${String(subsidy.note)}` : ''}
              </Alert>
            )}
            {priorityActions.length > 0 && (
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="h6" gutterBottom>
                    Priority improvement actions
                  </Typography>
                  {priorityActions.slice(0, 5).map((action) => (
                    <Typography key={action.action} variant="body2" sx={{ mb: 1 }}>
                      <strong>{action.priority}:</strong> {action.action}
                    </Typography>
                  ))}
                </CardContent>
              </Card>
            )}
            <ComplianceJsonPanel
              title="ZED readiness pack (20 parameters)"
              data={zed}
              filename="zed-readiness-pack.json"
            />
          </Stack>
        );
      }
      case 'product-pcf':
        return (
          <Stack spacing={2}>
            <Alert severity="info">
              Register products for ISO 14067 PCF. Full PDF reports are under Disclosure reports.
            </Alert>
            <Button component={RouterLink} to={reportingTabHref('iso14067')} variant="contained">
              Generate ISO 14067 report
            </Button>
            <ComplianceJsonPanel
              title="Registered product footprints"
              data={modules.productFootprints}
              filename="product-footprints.json"
            />
          </Stack>
        );
      case 'carbon-market': {
        const icmPack = modules.indianCarbonMarket as IcmIntegrationConfig & Record<string, unknown>;
        const configured = (icmPack?.registryStatus as { configured?: boolean })?.configured;
        return (
          <Stack spacing={2}>
            <Alert severity={configured ? 'success' : 'info'}>
              Registry alignment and credit retirement are managed in the Carbon Marketplace. This section
              tracks compliance readiness only.
            </Alert>
            <ComplianceJsonPanel
              title="Indian carbon market alignment"
              data={modules.indianCarbonMarket}
              filename="indian-carbon-market.json"
            />
            <Button component={RouterLink} to="/carbon-marketplace" variant="contained">
              Open carbon marketplace
            </Button>
          </Stack>
        );
      }
      case 'data-sync': {
        const connectors = (modules.accountingSync || []) as Record<string, unknown>[];
        const upstreamSupplierTier1 = (modules.upstreamSupplierTier1 || {}) as {
          summary?: Record<string, unknown>;
          suppliers?: Record<string, unknown>[];
          submissions?: Record<string, unknown>[];
        };
        const tier1Uplift = (modules.tier1Uplift || {}) as {
          currentTier1SharePct?: number;
          targetTier1SharePct?: number;
          readinessLevel?: string;
          gaps?: string[];
          actions?: Array<{ action: string; path: string; priority: string }>;
        };
        return (
          <Box>
            <QuantificationMethodBanner
              summary={{
                tier1SharePct: tier1Uplift.currentTier1SharePct,
                spendBasedSharePct: dataQualityAdvisory?.spendProxySharePct,
                primaryBasis: (tier1Uplift.currentTier1SharePct || 0) >= 35 ? 'activity_based' : 'spend_based',
              }}
            />
            <ComplianceReadinessGapPanel
              moduleGapDetails={moduleGapDetails}
              moduleKeys={['accountingSync']}
              title="Tier 1 data gaps (Zoho/Tally + metered bills)"
              period={period}
              onResolved={() => void load()}
            />
            <SupplierPrimaryDataPanel
              summary={upstreamSupplierTier1.summary as never}
              initialSuppliers={upstreamSupplierTier1.suppliers as never}
              initialSubmissions={upstreamSupplierTier1.submissions as never}
            />
            <Box sx={{ mb: 2 }}>
              <CarbonPassportPanel />
            </Box>
            {tier1Uplift.currentTier1SharePct != null && (
              <Alert severity={tier1Uplift.readinessLevel === 'tier1_ready' ? 'success' : 'warning'} sx={{ mb: 2 }}>
                Tier 1 activity-based share: <strong>{tier1Uplift.currentTier1SharePct}%</strong>
                {' '}(target {tier1Uplift.targetTier1SharePct ?? 50}%).
              </Alert>
            )}
            {(tier1Uplift.actions || []).length > 0 && (
              <Card variant="outlined" sx={{ mb: 2 }}>
                <CardContent>
                  <Typography variant="subtitle1" gutterBottom>
                    Activity-data uplift actions
                  </Typography>
                  <Stack spacing={1}>
                    {tier1Uplift.actions?.map((item) => (
                      <Box key={item.action}>
                        <Typography variant="body2">
                          <strong>{item.priority}:</strong> {item.action}
                        </Typography>
                        <Button component={RouterLink} to={item.path} size="small">
                          Open
                        </Button>
                      </Box>
                    ))}
                  </Stack>
                </CardContent>
              </Card>
            )}
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Connector</TableCell>
                  <TableCell>Import</TableCell>
                  <TableCell>API sync</TableCell>
                  <TableCell>Status</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {connectors.map((c) => (
                  <TableRow key={String(c.id)}>
                    <TableCell>{String(c.name)}</TableCell>
                    <TableCell>{c.supportsImport ? 'Yes' : 'No'}</TableCell>
                    <TableCell>{c.supportsApiSync ? 'Yes' : 'No'}</TableCell>
                    <TableCell>{c.syncReady ? 'Ready' : String(c.recommendation)}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
            <Button component={RouterLink} to="/data?section=connectors" sx={{ mt: 2 }}>
              Configure data connectors
            </Button>
          </Box>
        );
      }
      default:
        return null;
    }
  };

  return (
    <ComplianceTrackShell
      trackTitle={isEnterprise ? 'India regulatory compliance' : 'India market compliance'}
      trackDescription={
        isEnterprise
          ? 'SEBI BRSR and XBRL for listed entities, BRSR Core value chain, assurance, PAT-style intensity, SBTi, and domestic carbon markets.'
          : 'Mandatory and market-driven requirements for Indian MSMEs: BRSR Core value chain, assurance, MSME ZED certification, PAT-style intensity, SBTi, and domestic carbon markets.'
      }
      trackPath={isEnterprise ? '/enterprise/compliance' : '/compliance/india'}
      sectionGroups={INDIA_COMPLIANCE_GROUPS}
      activeSection={section}
      onSectionChange={setSection}
      period={period}
      onPeriodChange={setPeriod}
      loading={loading}
    >
      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}
      {renderSection()}
    </ComplianceTrackShell>
  );
};

export default IndiaComplianceTrack;
