import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  FormControl,
  FormControlLabel,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  Switch,
  TextField,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { reportingTabHref } from '../../constants/reportingTabs';
import ApiService from '../../services/api';
import {
  EXPORT_COMPLIANCE_GROUPS,
  EXPORT_COMPLIANCE_SECTIONS,
  unwrapComplianceHubPayload,
} from '../../constants/complianceHub';
import { useUrlSectionParam } from '../../hooks/useUrlSectionParam';
import { useOrchestrationEvents } from '../../hooks/useOrchestrationEvents';
import ComplianceTrackShell from './ComplianceTrackShell';
import ComplianceReadinessGrid from './ComplianceReadinessGrid';
import ComplianceReadinessGapPanel, { type ModuleGapBundle } from './ComplianceReadinessGapPanel';
import { EXPORT_READINESS_MODULE_KEYS } from '../../constants/readinessModuleKeys';
import ComplianceJsonPanel from './ComplianceJsonPanel';
import ProductPcfWorkspace from './ProductPcfWorkspace';
import CbamInstallationGpsCapture from './CbamInstallationGpsCapture';
import GpsGeotaggedCapture from './GpsGeotaggedCapture';
import BuyerQuestionnaireGapPanel, { BuyerPackReadiness } from './BuyerQuestionnaireGapPanel';
import BuyerQuestionnaireTemplateImport from './BuyerQuestionnaireTemplateImport';
import OrchestrationRunPanel, { type OrchestrationRunSummary, stagesFromRun } from './OrchestrationRunPanel';
import { MODULE_CHECK_LABELS } from '../../constants/orchestrationUxLabels';
import useReadinessLocale from '../../hooks/useReadinessLocale';
import { resolveTrackItemLabel } from '../../constants/complianceTrackLocale';
import ReportFilingReadinessBanner from '../reporting/ReportFilingReadinessBanner';
import CbamExportReadinessPanel from './CbamExportReadinessPanel';
import {
  isExportFormatClientAllowed,
  mapReportingDateRange,
  REPORTING_EXPORT_FORMATS,
} from '../../constants/reportingExports';

const SECTION_IDS = EXPORT_COMPLIANCE_SECTIONS.map((s) => s.id);

type ExportComplianceTrackProps = {
  variant?: 'msme' | 'enterprise';
};

const CBAM_CATEGORIES = [
  'cement',
  'iron_steel',
  'aluminium',
  'fertilisers',
  'electricity',
  'hydrogen',
];

const ExportComplianceTrack: React.FC<ExportComplianceTrackProps> = ({ variant = 'msme' }) => {
  const isEnterprise = variant === 'enterprise';
  useOrchestrationEvents(true);
  const { strings, locale } = useReadinessLocale();
  const [section, setSection] = useUrlSectionParam('overview', SECTION_IDS);
  const [period, setPeriod] = useState('annual');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [track, setTrack] = useState<Record<string, unknown> | null>(null);
  const [exportProfile, setExportProfile] = useState<Record<string, unknown>>({});
  const [saving, setSaving] = useState(false);
  const [newQuestionnaire, setNewQuestionnaire] = useState({
    buyerName: '',
    framework: 'csrd',
    buyerContactEmail: '',
    dueDate: '',
  });
  const [exportPack, setExportPack] = useState<unknown>(null);
  const [downloadingBundle, setDownloadingBundle] = useState(false);
  const [verificationBusyKey, setVerificationBusyKey] = useState<string | null>(null);
  const [cbamVerificationBusyId, setCbamVerificationBusyId] = useState<string | null>(null);
  const [cbamOrchestrating, setCbamOrchestrating] = useState(false);
  const [cbamRegistryDownloading, setCbamRegistryDownloading] = useState(false);
  const [cbamRegistryFeedback, setCbamRegistryFeedback] = useState<string | null>(null);
  const [orchestrationFeedback, setOrchestrationFeedback] = useState<string | null>(null);
  const [lastCbamRun, setLastCbamRun] = useState<OrchestrationRunSummary | null>(null);
  const [cbamStages, setCbamStages] = useState<Array<{ stage: string; status: string; durationMs?: number | null }>>([]);

  const runCbamReadinessOrchestration = async () => {
    setCbamOrchestrating(true);
    setOrchestrationFeedback(null);
    try {
      const res = await ApiService.orchestrateCbamReadiness({ period, applyChanges: true });
      const data = (res as { data?: Record<string, unknown> })?.data;
      setCbamStages((data?.stages as typeof cbamStages) || []);
      setLastCbamRun((data?.orchestrationRun as OrchestrationRunSummary) || {
        orchestratorType: 'cbam_readiness',
        scoreAfter: (data?.readinessSnapshot as { score?: number })?.score
          ?? data?.overallReadinessScore as number,
        message: data?.message as string,
        lastRunAt: new Date().toISOString(),
        success: data?.success !== false
      });
      setOrchestrationFeedback(String(data?.message || strings.cbamReadinessComplete));
      await load();
    } catch (e) {
      setOrchestrationFeedback(e instanceof Error ? e.message : strings.cbamReadinessFailed);
    } finally {
      setCbamOrchestrating(false);
    }
  };

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getComplianceExportTrack({ period });
      const data = unwrapComplianceHubPayload<Record<string, unknown>>(res);
      setTrack(data);
      if (data?.exportProfile) {
        setExportProfile(data.exportProfile as Record<string, unknown>);
      }
      const agentOrch = (data?.agentOrchestration || {}) as {
        lastRuns?: Record<string, OrchestrationRunSummary>;
      };
      if (agentOrch.lastRuns?.cbam_readiness) {
        setLastCbamRun(agentOrch.lastRuns.cbam_readiness);
        setCbamStages(stagesFromRun(agentOrch.lastRuns.cbam_readiness));
      }
    } catch (e) {
      setTrack(null);
      setError(e instanceof Error ? e.message : 'Failed to load export compliance track');
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => {
    load();
  }, [load]);

  const modules = (track?.modules || {}) as Record<string, unknown>;
  const readiness = (track?.readiness || {}) as Record<string, string>;
  const packValidation = (track?.packValidation || {}) as Record<string, {
    valid?: boolean;
    missingFields?: string[];
    warnings?: string[];
    verificationRequired?: Array<{ field?: string; message?: string }>;
    framework?: string;
  }>;
  const buyerPackReadiness = (track?.buyerPackReadiness || null) as BuyerPackReadiness | null;
  const exportModuleScores = (track?.moduleScores || {}) as Record<string, number | null>;
  const moduleGapDetails = (track?.moduleGapDetails || {}) as Record<string, ModuleGapBundle>;
  const frameworkReadiness = (track?.frameworkReadiness || {}) as {
    cbam?: {
      reportReadinessLevel?: string;
      reportReadinessLabel?: string;
      readinessType?: string;
      blockedReasons?: string[];
      filingDisclaimer?: string;
    };
  };
  const cbamReadinessSnapshot = frameworkReadiness.cbam || {};
  const cbamRegistryFormat = REPORTING_EXPORT_FORMATS.cbam.find((format) => format.id === 'registry');

  const handleCbamRegistryDownload = async () => {
    if (!cbamRegistryFormat) {
      return;
    }
    const readinessLevel = cbamReadinessSnapshot.reportReadinessLevel || 'prep_draft';
    if (!isExportFormatClientAllowed(cbamRegistryFormat, readinessLevel)) {
      setCbamRegistryFeedback('CBAM registry CSV requires filing-ready status. Run CBAM readiness check first.');
      return;
    }

    setCbamRegistryDownloading(true);
    setCbamRegistryFeedback(null);
    try {
      const { blob, fileName } = await ApiService.exportReportArtifact({
        reportType: 'cbam',
        format: cbamRegistryFormat.apiFormat,
        dateRange: mapReportingDateRange('cbam', '3months'),
      });
      const blobUrl = window.URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = blobUrl;
      anchor.download = fileName || `CBAM_registry_${new Date().toISOString().slice(0, 10)}.csv`;
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      window.URL.revokeObjectURL(blobUrl);
      setCbamRegistryFeedback('CBAM registry CSV downloaded.');
    } catch (e) {
      setCbamRegistryFeedback(e instanceof Error ? e.message : 'Failed to download CBAM registry CSV.');
    } finally {
      setCbamRegistryDownloading(false);
    }
  };

  const packVerificationItems = Object.values(packValidation).flatMap((pack) => (
    (pack.verificationRequired || []).map((item) => ({
      framework: pack.framework || 'Buyer pack',
      field: item.field || '',
      ...item
    }))
  ));

  const handlePackVerificationAction = async (
    item: { framework: string; field: string; message?: string },
    confirmed: boolean
  ) => {
    const key = `${item.framework}:${item.field}`;
    setVerificationBusyKey(key);
    try {
      await ApiService.confirmPackVerification({
        framework: item.framework,
        field: item.field,
        confirmed,
        note: confirmed ? 'Confirmed in Export Hub.' : 'Flagged for correction in Export Hub.'
      });
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to update pack verification');
    } finally {
      setVerificationBusyKey(null);
    }
  };

  const handleCbamDocumentationAction = async (
    item: { id?: string; field?: string; title?: string },
    confirmed: boolean
  ) => {
    const documentationId = item.id || item.field || '';
    if (!documentationId) return;
    setCbamVerificationBusyId(documentationId);
    try {
      await ApiService.confirmCbamDocumentation({
        documentationId,
        confirmed,
        note: confirmed ? 'Confirmed in Export Hub CBAM section.' : 'Flagged for correction in Export Hub.'
      });
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to update CBAM documentation verification');
    } finally {
      setCbamVerificationBusyId(null);
    }
  };

  const saveExportProfile = async () => {
    setSaving(true);
    try {
      await ApiService.updateComplianceExportProfile(exportProfile);
      await load();
    } finally {
      setSaving(false);
    }
  };

  const addQuestionnaire = async () => {
    if (!newQuestionnaire.buyerName.trim()) return;
    setSaving(true);
    try {
      await ApiService.createSupplierQuestionnaire({
        ...newQuestionnaire,
        dueDate: newQuestionnaire.dueDate ? new Date(newQuestionnaire.dueDate).toISOString() : undefined,
      });
      setNewQuestionnaire({ buyerName: '', framework: 'csrd', buyerContactEmail: '', dueDate: '' });
      await load();
    } finally {
      setSaving(false);
    }
  };

  const loadExportPack = async (framework: string) => {
    const res = await ApiService.getComplianceExportPack(framework, { period });
    setExportPack((res as { data?: unknown })?.data ?? null);
  };

  const downloadBuyerPackBundle = async () => {
    setDownloadingBundle(true);
    try {
      const blob = await ApiService.downloadBuyerPackExport({
        period,
        includeCbam: Boolean((exportProfile.cbamGoodsCategories as string[])?.length),
        includeEudr: Boolean(exportProfile.eudrApplicable),
      });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = `buyer-pack-${period}.zip`;
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to download buyer pack bundle');
    } finally {
      setDownloadingBundle(false);
    }
  };

  const renderSection = () => {
    if (loading && !track) {
      return (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
          <CircularProgress />
        </Box>
      );
    }

    if (!track) {
      return null;
    }

    switch (section) {
      case 'overview':
        return (
          <>
            <Alert severity="info" sx={{ mb: 2 }} action={(
              <Button component={RouterLink} to="/compliance" variant="contained" size="small">
                Check readiness
              </Button>
            )}>
              <Typography variant="body2">
                {strings.exportHubHandoff}
              </Typography>
            </Alert>
            <Card variant="outlined" sx={{ mb: 3 }}>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Export profile
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="Primary export regions (comma-separated)"
                      fullWidth
                      value={(exportProfile.primaryRegions as string[])?.join(', ') || ''}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          primaryRegions: e.target.value.split(',').map((s) => s.trim()).filter(Boolean),
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <FormControl fullWidth>
                      <InputLabel>CBAM goods</InputLabel>
                      <Select
                        multiple
                        label="CBAM goods"
                        value={(exportProfile.cbamGoodsCategories as string[]) || []}
                        onChange={(e) =>
                          setExportProfile({
                            ...exportProfile,
                            cbamGoodsCategories:
                              typeof e.target.value === 'string'
                                ? e.target.value.split(',')
                                : e.target.value,
                          })
                        }
                        renderValue={(selected) => (selected as string[]).join(', ')}
                      >
                        {CBAM_CATEGORIES.map((cat) => (
                          <MenuItem key={cat} value={cat}>
                            {cat.replace(/_/g, ' ')}
                          </MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={Boolean(exportProfile.eudrApplicable)}
                          onChange={(e) =>
                            setExportProfile({ ...exportProfile, eudrApplicable: e.target.checked })
                          }
                        />
                      }
                      label="EUDR applies (agri/forest commodities to EU)"
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <TextField
                      label="TCFD physical risks (comma-separated — confirm site-specific risks)"
                      fullWidth
                      multiline
                      minRows={2}
                      value={(exportProfile.tcfdPhysicalRisks as string[])?.join(', ') || ''}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          tcfdPhysicalRisks: e.target.value.split(',').map((s) => s.trim()).filter(Boolean),
                        })
                      }
                      helperText="Leave blank to use sector defaults (flagged for verification in TCFD pack)."
                    />
                  </Grid>
                </Grid>
                <Button sx={{ mt: 2 }} variant="contained" onClick={saveExportProfile} disabled={saving}>
                  Save export profile
                </Button>
              </CardContent>
            </Card>
            <ComplianceReadinessGrid
              locale={locale}
              items={[
                { key: 'cbam', label: resolveTrackItemLabel('cbam', locale, 'CBAM'), status: readiness.cbam, score: exportModuleScores.cbam, threshold: 80 },
                { key: 'productPcf', label: resolveTrackItemLabel('productPcf', locale, 'Product PCF'), status: readiness.productPcf, score: exportModuleScores.productPcf, threshold: 85 },
                { key: 'csrd', label: resolveTrackItemLabel('csrd', locale, 'CSRD'), status: readiness.csrd, score: exportModuleScores.csrd },
                { key: 'cdp', label: resolveTrackItemLabel('cdp', locale, 'CDP'), status: readiness.cdp, score: exportModuleScores.cdp },
                { key: 'gri', label: resolveTrackItemLabel('gri', locale, 'GRI 305'), status: readiness.gri, score: exportModuleScores.gri },
                { key: 'tcfd', label: resolveTrackItemLabel('tcfd', locale, 'TCFD'), status: readiness.tcfd, score: exportModuleScores.tcfd },
                { key: 'supplierPortal', label: resolveTrackItemLabel('supplierPortal', locale, 'Questionnaires'), status: readiness.supplierPortal, score: exportModuleScores.supplierPortal, threshold: 75 },
                { key: 'eudr', label: resolveTrackItemLabel('eudr', locale, 'EUDR'), status: readiness.eudr, score: exportModuleScores.eudr },
                { key: 'ecovadis', label: resolveTrackItemLabel('ecovadis', locale, 'EcoVadis'), status: readiness.ecovadis, score: exportModuleScores.ecovadis },
              ]}
            />
            {packVerificationItems.length > 0 ? (
              <Card variant="outlined" sx={{ mt: 2 }}>
                <CardContent>
                  <Typography variant="subtitle2" gutterBottom>
                    Guided verification — confirm or fix before buyer submission
                  </Typography>
                  <Stack spacing={1.5}>
                    {packVerificationItems.map((item) => {
                      const key = `${item.framework}-${item.field}-${item.message}`;
                      const busy = verificationBusyKey === `${item.framework}:${item.field}`;
                      return (
                        <Box
                          key={key}
                          sx={{
                            display: 'flex',
                            flexWrap: 'wrap',
                            alignItems: 'center',
                            gap: 1,
                            justifyContent: 'space-between'
                          }}
                        >
                          <Box sx={{ flex: 1, minWidth: 220 }}>
                            <Chip size="small" label={item.framework} sx={{ mr: 1 }} />
                            <Typography variant="body2" component="span">
                              {item.message}
                            </Typography>
                          </Box>
                          <Stack direction="row" spacing={1}>
                            <Button
                              size="small"
                              variant="contained"
                              disabled={busy}
                              onClick={() => handlePackVerificationAction(item, true)}
                            >
                              Confirm
                            </Button>
                            <Button
                              size="small"
                              variant="outlined"
                              color="warning"
                              disabled={busy}
                              onClick={() => handlePackVerificationAction(item, false)}
                            >
                              Fix
                            </Button>
                          </Stack>
                        </Box>
                      );
                    })}
                  </Stack>
                </CardContent>
              </Card>
            ) : null}
            <Alert severity="info" sx={{ mt: 2 }}>
              Download a ZIP bundle with CDP, GRI, CSRD, TCFD, EcoVadis packs, product footprints,
              and an evidence index for buyer submissions.
            </Alert>
            <Button
              variant="contained"
              sx={{ mt: 1 }}
              onClick={downloadBuyerPackBundle}
              disabled={downloadingBundle}
            >
              {downloadingBundle ? 'Preparing bundle…' : 'Download buyer pack ZIP'}
            </Button>
            <ComplianceReadinessGapPanel
              moduleGapDetails={moduleGapDetails}
              moduleKeys={[...EXPORT_READINESS_MODULE_KEYS]}
              title="Export readiness gaps"
              period={period}
              onResolved={() => void load()}
            />
          </>
        );
      case 'cbam': {
        const cbamExporter = (modules.cbamExporter || {}) as {
          documentationVerification?: {
            documentationVerifications?: Array<{
              id?: string;
              title?: string;
              status?: string;
              reason?: string;
              requiredBillTypes?: string[];
              owner?: string;
            }>;
            verificationRequired?: Array<{
              id?: string;
              field?: string;
              title?: string;
              message?: string;
              requiredBillTypes?: string[];
              owner?: string;
            }>;
            readinessScore?: number;
            tier1InstallationStatus?: { derived?: boolean; totalKgCo2e?: number };
            installationBoundaryStatus?: {
              verified?: boolean;
              tier1BoundaryReady?: boolean;
              proximityKm?: number | null;
              bestMatch?: { reason?: string; documentId?: string };
              referenceSource?: string;
            };
            installationBoundaryVerification?: {
              installationBoundaryStatus?: {
                verified?: boolean;
                tier1BoundaryReady?: boolean;
                proximityKm?: number | null;
                bestMatch?: { reason?: string; documentId?: string };
              };
            };
          };
        };
        const cbamDocVerification = cbamExporter.documentationVerification;
        const cbamDocItems = cbamDocVerification?.verificationRequired || [];
        const cbamDocStatuses = cbamDocVerification?.documentationVerifications || [];
        const installationBoundaryStatus =
          cbamDocVerification?.installationBoundaryStatus
          || cbamDocVerification?.installationBoundaryVerification?.installationBoundaryStatus
          || null;

        return (
          <Stack spacing={2}>
            <ReportFilingReadinessBanner
              framework="CBAM"
              readinessLevel={cbamReadinessSnapshot.reportReadinessLevel}
              readinessLabel={cbamReadinessSnapshot.reportReadinessLabel}
              readinessType={cbamReadinessSnapshot.readinessType || 'cbam_registry'}
              filingDisclaimer={cbamReadinessSnapshot.filingDisclaimer}
              blockedReasons={cbamReadinessSnapshot.blockedReasons || []}
              variant={
                cbamReadinessSnapshot.reportReadinessLevel === 'filing_ready' ? 'info' : 'warning'
              }
              period={period}
              onResolved={() => void load()}
            />
            <ComplianceReadinessGapPanel
              moduleGapDetails={moduleGapDetails}
              moduleKeys={['cbam', 'productPcf']}
              title="CBAM & product footprint gaps"
              period={period}
              onResolved={() => void load()}
            />
            {orchestrationFeedback ? <Alert severity="info">{orchestrationFeedback}</Alert> : null}
            {cbamRegistryFeedback ? <Alert severity="info">{cbamRegistryFeedback}</Alert> : null}
            <OrchestrationRunPanel
              lastRun={lastCbamRun}
              stages={cbamStages}
              title={MODULE_CHECK_LABELS.cbam.panelTitle}
              running={cbamOrchestrating}
              runningStageLabel={MODULE_CHECK_LABELS.cbam.running}
              showEmptyPrompt
            />
            <Typography variant="body2" color="text.secondary">
              {MODULE_CHECK_LABELS.cbam.subtitle}
            </Typography>
            <Stack direction="row" spacing={1} flexWrap="wrap">
              <Button
                variant="contained"
                disabled={cbamOrchestrating}
                onClick={() => void runCbamReadinessOrchestration()}
              >
                {cbamOrchestrating ? MODULE_CHECK_LABELS.cbam.running : MODULE_CHECK_LABELS.cbam.button}
              </Button>
              <Button component={RouterLink} to={reportingTabHref('cbam')} variant="outlined">
                Open CBAM quarterly report
              </Button>
              <Button
                variant="outlined"
                disabled={
                  cbamRegistryDownloading
                  || !cbamRegistryFormat
                  || !isExportFormatClientAllowed(
                    cbamRegistryFormat,
                    cbamReadinessSnapshot.reportReadinessLevel
                  )
                }
                onClick={() => void handleCbamRegistryDownload()}
              >
                {cbamRegistryDownloading ? 'Preparing registry CSV…' : 'Download CBAM registry CSV'}
              </Button>
            </Stack>
            <CbamInstallationGpsCapture
              period={period}
              installationBoundaryStatus={installationBoundaryStatus}
              onComplete={() => void load()}
            />
            <ComplianceReadinessGrid
              locale={locale}
              items={[{ key: 'cbam', label: resolveTrackItemLabel('cbam', locale, 'CBAM readiness'), status: readiness.cbam }]}
            />
            {cbamDocVerification ? (
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="subtitle2" gutterBottom>
                    CBAM documentation checklist
                  </Typography>
                  <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                    Score: {cbamDocVerification.readinessScore ?? 0}%
                    {cbamDocVerification.tier1InstallationStatus?.derived
                      ? ` · Tier 1 path: ${cbamDocVerification.tier1InstallationStatus.totalKgCo2e ?? 0} kg CO₂e`
                      : ' · Tier 1 path: pending verified energy/fuel bills'}
                  </Typography>
                  <Stack spacing={1.5}>
                    {cbamDocStatuses.map((item) => (
                      <Box key={item.id}>
                        <Chip
                          size="small"
                          label={item.status === 'verified_internal' ? 'Verified' : item.status || 'pending'}
                          color={item.status === 'verified_internal' ? 'success' : item.status === 'needs_review' ? 'warning' : 'default'}
                          sx={{ mr: 1 }}
                        />
                        <Typography variant="body2" component="span" fontWeight={600}>
                          {item.title}
                        </Typography>
                        <Typography variant="body2" color="text.secondary" display="block">
                          {item.reason}
                        </Typography>
                        {item.requiredBillTypes?.length ? (
                          <Typography variant="caption" color="text.secondary" display="block">
                            Bills: {item.requiredBillTypes.join(', ')}
                          </Typography>
                        ) : null}
                      </Box>
                    ))}
                  </Stack>
                  {cbamDocItems.length > 0 ? (
                    <Stack spacing={1.5} sx={{ mt: 2 }}>
                      <Typography variant="subtitle2">Confirm or fix</Typography>
                      {cbamDocItems.map((item) => {
                        const docId = item.id || item.field || '';
                        const busy = cbamVerificationBusyId === docId;
                        return (
                          <Box
                            key={docId}
                            sx={{
                              display: 'flex',
                              flexWrap: 'wrap',
                              alignItems: 'center',
                              gap: 1,
                              justifyContent: 'space-between'
                            }}
                          >
                            <Box sx={{ flex: 1, minWidth: 220 }}>
                              <Typography variant="body2" fontWeight={600}>{item.title}</Typography>
                              <Typography variant="body2">{item.message}</Typography>
                            </Box>
                            <Stack direction="row" spacing={1}>
                              <Button
                                size="small"
                                variant="contained"
                                disabled={busy}
                                onClick={() => handleCbamDocumentationAction(item, true)}
                              >
                                Confirm
                              </Button>
                              <Button
                                size="small"
                                variant="outlined"
                                color="warning"
                                disabled={busy}
                                onClick={() => handleCbamDocumentationAction(item, false)}
                              >
                                Fix
                              </Button>
                            </Stack>
                          </Box>
                        );
                      })}
                    </Stack>
                  ) : null}
                </CardContent>
              </Card>
            ) : null}
            <CbamExportReadinessPanel showHydrogen />
            <ComplianceJsonPanel
              title="CBAM exporter pack"
              data={modules.cbamExporter}
              filename="cbam-exporter-pack.json"
            />
          </Stack>
        );
      }
      case 'product-pcf':
        return <ProductPcfWorkspace />;
      case 'csrd-supplier':
        return (
          <Stack spacing={2}>
            <Button variant="outlined" onClick={() => loadExportPack('csrd')}>
              Refresh CSRD pack
            </Button>
            <ComplianceJsonPanel
              title="CSRD / ESRS supplier datapoints"
              data={exportPack || modules.csrdSupplier}
              filename="csrd-supplier-pack.json"
            />
          </Stack>
        );
      case 'cdp': {
        const cdpPack = (exportPack || modules.cdpClimate || {}) as {
          sectionsIncluded?: string[];
          c1?: Record<string, unknown>;
          c7?: { scope1?: number; scope2?: number; scope3?: number };
        };
        const sections = cdpPack.sectionsIncluded || [];
        return (
          <Stack spacing={2}>
            <Alert severity={sections.length >= 15 ? 'success' : 'info'}>
              CDP Climate Change questionnaire: {sections.length || 0}/15 sections mapped (C1–C15).
              {sections.length >= 15
                ? ' Pack ready for buyer portal upload preparation.'
                : ' Complete missing sections before CDP submission.'}
            </Alert>
            <Button variant="outlined" onClick={() => loadExportPack('cdp')}>
              Refresh CDP mapping
            </Button>
            <ComplianceJsonPanel
              title="CDP Climate Change mapping (C1–C15)"
              data={exportPack || modules.cdpClimate}
              filename="cdp-climate-pack.json"
            />
          </Stack>
        );
      }
      case 'gri':
        return (
          <Stack spacing={2}>
            <Button variant="outlined" onClick={() => loadExportPack('gri')}>
              Refresh GRI 305 pack
            </Button>
            <ComplianceJsonPanel
              title="GRI Standards (305 emissions)"
              data={exportPack || modules.griStandards}
              filename="gri-305-emissions-pack.json"
            />
          </Stack>
        );
      case 'tcfd-issb':
        return (
          <Stack spacing={2}>
            <Button variant="outlined" onClick={() => loadExportPack('tcfd')}>
              Refresh TCFD / ISSB pack
            </Button>
            <ComplianceJsonPanel
              title="TCFD / IFRS S2 structure"
              data={exportPack || modules.tcfdIssb}
              filename="tcfd-issb-pack.json"
            />
          </Stack>
        );
      case 'supplier-portal':
        return (
          <Stack spacing={2}>
            <BuyerQuestionnaireTemplateImport onImported={() => void load()} />
            <Card variant="outlined">
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  New buyer questionnaire
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={3}>
                    <TextField
                      label="Buyer name"
                      fullWidth
                      value={newQuestionnaire.buyerName}
                      onChange={(e) =>
                        setNewQuestionnaire({ ...newQuestionnaire, buyerName: e.target.value })
                      }
                    />
                  </Grid>
                  <Grid item xs={12} md={3}>
                    <TextField
                      label="Buyer contact email"
                      fullWidth
                      type="email"
                      value={newQuestionnaire.buyerContactEmail}
                      onChange={(e) =>
                        setNewQuestionnaire({ ...newQuestionnaire, buyerContactEmail: e.target.value })
                      }
                    />
                  </Grid>
                  <Grid item xs={12} md={2}>
                    <TextField
                      label="Due date"
                      fullWidth
                      type="date"
                      InputLabelProps={{ shrink: true }}
                      value={newQuestionnaire.dueDate}
                      onChange={(e) =>
                        setNewQuestionnaire({ ...newQuestionnaire, dueDate: e.target.value })
                      }
                    />
                  </Grid>
                  <Grid item xs={12} md={2}>
                    <FormControl fullWidth>
                      <InputLabel>Framework</InputLabel>
                      <Select
                        label="Framework"
                        value={newQuestionnaire.framework}
                        onChange={(e) =>
                          setNewQuestionnaire({
                            ...newQuestionnaire,
                            framework: e.target.value,
                          })
                        }
                      >
                        <MenuItem value="brsr_core">BRSR Core</MenuItem>
                        <MenuItem value="cdp">CDP</MenuItem>
                        <MenuItem value="csrd">CSRD</MenuItem>
                        <MenuItem value="ecovadis">EcoVadis</MenuItem>
                        <MenuItem value="custom">Custom</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} md={2}>
                    <Button variant="contained" onClick={addQuestionnaire} disabled={saving} fullWidth sx={{ height: '100%' }}>
                      Add request
                    </Button>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
            <BuyerQuestionnaireGapPanel buyerPackReadiness={buyerPackReadiness} />
            <Stack direction="row" spacing={1} flexWrap="wrap">
              <Button variant="outlined" onClick={downloadBuyerPackBundle} disabled={downloadingBundle}>
                {downloadingBundle ? 'Preparing…' : 'Download buyer pack bundle'}
              </Button>
            </Stack>
          </Stack>
        );
      case 'eudr':
        return (
          <Stack spacing={2}>
            <GpsGeotaggedCapture
              workflow="eudr_plot_evidence"
              period={period}
              onComplete={() => void load()}
            />
            <ComplianceJsonPanel
              title="EUDR due diligence skeleton"
              data={modules.eudr}
              filename="eudr-pack.json"
            />
          </Stack>
        );
      case 'ecovadis':
        return (
          <Stack spacing={2}>
            <Button variant="outlined" onClick={() => loadExportPack('ecovadis')}>
              Refresh EcoVadis pack
            </Button>
            <ComplianceJsonPanel
              title="EcoVadis-aligned datapoints"
              data={exportPack || modules.ecovadis}
              filename="ecovadis-pack.json"
            />
          </Stack>
        );
      default:
        return null;
    }
  };

  return (
    <ComplianceTrackShell
      trackTitle={isEnterprise ? 'Global buyer disclosure' : 'Global export compliance'}
      trackDescription={
        isEnterprise
          ? 'CDP C1–C15, CSRD value-chain datapoints, TCFD/ISSB S2, and buyer questionnaire packs for listed and large enterprises.'
          : 'Requirements for Indian exporters: EU CBAM, product PCF, CSRD value-chain datapoints, CDP, TCFD/ISSB S2, buyer questionnaires, EUDR, and EcoVadis.'
      }
      trackPath={isEnterprise ? '/enterprise/compliance' : '/compliance/export'}
      sectionGroups={EXPORT_COMPLIANCE_GROUPS}
      activeSection={section}
      onSectionChange={setSection}
      period={period}
      onPeriodChange={setPeriod}
      loading={loading}
    >
      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}
      {renderSection()}
    </ComplianceTrackShell>
  );
};

export default ExportComplianceTrack;
